/* Lessons and additions for guidance topics that had no lesson yet:
   B4 classification and single-celled organisms; B1.6 drugs; P3 sound, hearing and light;
   plus extra points for topics only partly covered. Loaded after learn-repro.js and the deep-*.js files. */
'use strict';
function extendLesson(id, o) {
  const L = LESSONS.find(l => l.id === id); if (!L) return;
  if (o.points) L.points.push(...o.points);
  if (o.title) L.title = o.title;
  if (o.deep) (DEEP[id] ||= []).push(...o.deep);
  if (o.quiz) L.quiz.push(...o.quiz);
}

/* ---------------- new biology lessons ---------------- */
lessonAfter('repro-plants', {id: 'classification', code: 'B15', subject: 'biology', title: 'Classification and single-celled organisms', level: 'GCSE',
  search: 'KS3 classification vertebrates invertebrates kingdoms protists',
  intro: 'There are millions of species. Scientists sort them into groups by their shared features. The guidance asks you to know that species differ, the major taxonomic groups, and the adaptations of some single-celled organisms.',
  goals: ['Name the five kingdoms and their features', 'Classify vertebrates into five classes and invertebrates into major groups', 'Classify plants into their major groups', 'Describe how Amoeba, Euglena and Paramecium are adapted', 'Use and build a dichotomous key'],
  points: [
    {tag: 'rule', title: 'Why we classify', text: 'Grouping organisms by shared features makes them easier to study and identify, and shows how closely related they are. The groups get smaller and more alike at each level: kingdom, phylum, class, order, family, genus, species. Each species has a two-part scientific name (genus then species), such as <em>Panthera leo</em> for the lion.'},
    {tag: 'rule', title: 'Species', text: 'A species is a group of organisms that can breed together to produce fertile offspring. Different species differ in their features and cannot normally do this: a horse and a donkey can produce a mule, but mules are infertile.'},
    {tag: 'rule', title: 'The five kingdoms', text: '<strong>Animals</strong>: many cells, no cell walls or chlorophyll, feed on other organisms, usually move. <strong>Plants</strong>: many cells, cellulose cell walls, chlorophyll, make their own food by photosynthesis. <strong>Fungi</strong> (mushrooms, moulds, yeast): no chlorophyll, cell walls of chitin, feed by releasing enzymes onto dead material and absorbing the products, reproduce with spores; many are made of thread-like hyphae. <strong>Protists</strong> (protoctists): mostly single cells with a nucleus. <strong>Prokaryotes</strong> (bacteria): single cells with no nucleus. Viruses are not usually counted as living, because they cannot reproduce outside a host cell.'},
    {tag: 'rule', title: 'Vertebrates: animals with a backbone', text: '<strong>Fish</strong>: scales, fins, breathe with gills, lay eggs in water. <strong>Amphibians</strong> (frogs, newts): moist skin, young (tadpoles) live in water with gills, adults have lungs, lay eggs in water. <strong>Reptiles</strong> (snakes, lizards, turtles): dry scaly skin, lungs, lay leathery-shelled eggs on land. <strong>Birds</strong>: feathers, wings, beak, lungs, hard-shelled eggs, keep a constant body temperature. <strong>Mammals</strong>: hair or fur, lungs, most give birth to live young and all feed them milk, keep a constant body temperature.'},
    {tag: 'rule', title: 'Invertebrates: no backbone', text: '<strong>Arthropods</strong> have jointed legs and a hard exoskeleton: <em>insects</em> (6 legs, 3 body parts, usually wings), <em>arachnids</em> (8 legs, 2 body parts: spiders, scorpions), <em>crustaceans</em> (many legs, hard shell, mostly in water: crabs, woodlice), <em>myriapods</em> (many segments with many legs: centipedes, millipedes). <strong>Molluscs</strong> have a soft body, often with a shell (snails, slugs, octopuses). <strong>Annelids</strong> are segmented worms (earthworms). Others include <strong>cnidarians</strong> (jellyfish) and <strong>echinoderms</strong> (starfish).'},
    {tag: 'rule', title: 'Plants', text: '<strong>Mosses</strong>: small, no true roots, reproduce by spores, live in damp places. <strong>Ferns</strong>: roots, stems and feathery leaves, reproduce by spores. <strong>Conifers</strong>: trees with needle-like leaves, seeds made in cones. <strong>Flowering plants</strong>: flowers, seeds made inside fruits.'},
    {tag: 'rule', title: 'Amoeba', text: 'A single cell that lives in water. It moves and feeds by pushing out <strong>pseudopodia</strong> (“false feet”) of cytoplasm, which flow around food and engulf it in a food vacuole. A <strong>contractile vacuole</strong> collects excess water that enters by osmosis and pumps it out, so the cell does not burst.'},
    {tag: 'rule', title: 'Euglena', text: 'A single cell with features of both plants and animals. It has <strong>chloroplasts</strong> and photosynthesises in light, an <strong>eyespot</strong> that detects light, and a whip-like <strong>flagellum</strong> to swim towards it. In the dark it can feed on food in the water. It also has a contractile vacuole.'},
    {tag: 'rule', title: 'Paramecium', text: 'A slipper-shaped single cell covered in tiny hairs called <strong>cilia</strong>, which beat to move it through water and sweep food (such as bacteria) into its <strong>oral groove</strong>. It also has contractile vacuoles to remove excess water.'},
    {tag: 'rule', title: 'Keys', text: 'A dichotomous key identifies an organism by asking a series of questions, each with two answers (“Does it have legs? yes / no”). Good questions use features you can see and measure, not things that vary such as size or colour.'}
  ],
  labs: ['microscope', 'variation'],
  worked: [
    {q: 'An animal has 8 jointed legs and 2 body parts. Classify it.', steps: ['Jointed legs and a hard outer skeleton: arthropod.', 'Insects have 6 legs; crustaceans and myriapods have many.', '8 legs and 2 body parts: arachnid.'], a: 'An arthropod, in the arachnid group (for example a spider).'},
    {q: 'Explain why Euglena is hard to classify as a plant or an animal.', steps: ['Like plants, it has chloroplasts and can photosynthesise.', 'Like animals, it moves (using a flagellum) and can take in food from its surroundings.', 'So it does not fit either kingdom; it is placed with the protists.'], a: 'It has features of both, so it is classified as a protist.'}
  ],
  quiz: [
    {q: 'Which group has feathers and lays hard-shelled eggs?', opts: ['Reptiles', 'Birds', 'Mammals', 'Amphibians'], correct: 1, explain: 'Feathers are unique to birds.'},
    {q: 'Which is an insect?', opts: ['Spider (8 legs)', 'Woodlouse (14 legs)', 'Beetle (6 legs)', 'Centipede (many legs)'], correct: 2, explain: 'Insects have 6 legs and 3 body parts.'},
    {q: 'Fungi are not plants because they:', opts: ['have cell walls', 'have no chlorophyll and cannot photosynthesise', 'are single-celled', 'have a nucleus'], correct: 1, explain: 'Fungi feed by absorbing food from dead or living material.'},
    {q: 'What is the job of Amoeba’s contractile vacuole?', opts: ['Photosynthesis', 'Pumping out excess water', 'Movement', 'Digesting food'], correct: 1, explain: 'Water keeps entering by osmosis; the contractile vacuole removes it.'},
    {q: 'Paramecium moves using:', opts: ['pseudopodia', 'a flagellum', 'cilia', 'legs'], correct: 2, explain: 'Thousands of beating cilia.'},
    {q: 'Which plant group makes seeds in cones?', opts: ['Mosses', 'Ferns', 'Conifers', 'Flowering plants'], correct: 2, explain: 'Mosses and ferns use spores; flowering plants make seeds in fruits.'}
  ],
  challenges: [
    {prompt: 'A whale lives in the sea and has fins, but it is a mammal, not a fish. Give three features that show this.', marks: 3, answer: 'It breathes air with lungs (it surfaces to breathe), not gills. It gives birth to live young and feeds them milk. It has some hair and keeps a constant body temperature.'},
    {prompt: 'Explain how Amoeba is adapted to live as a single cell in fresh water.', marks: 3, answer: 'It has no fixed shape and pushes out pseudopodia to move and to engulf food, which is digested in food vacuoles. Being a single small cell it has a large surface area to volume ratio, so oxygen can diffuse in and carbon dioxide out across its membrane. Fresh water enters by osmosis, so its contractile vacuole collects and expels the excess water to stop it bursting.'}
  ],
  keywords: [['Species', 'Organisms that can breed together to produce fertile offspring.'], ['Vertebrate', 'An animal with a backbone.'], ['Invertebrate', 'An animal without a backbone.'], ['Arthropod', 'Invertebrate with jointed legs and an exoskeleton.'], ['Protist', 'A (mostly) single-celled organism with a nucleus.'], ['Dichotomous key', 'A key in which each step gives two choices.']],
  stretch: 'Modern classification uses DNA as well as appearance. Comparing DNA sequences led to the <strong>three-domain system</strong>: Bacteria, Archaea (prokaryotes that often live in extreme places) and Eukarya (everything with a nucleus). Species with more similar DNA share a more recent common ancestor.'
});

lessonAfter('classification', {id: 'drugs', code: 'B16', subject: 'biology', title: 'Drugs and their effects', level: 'GCSE',
  search: 'KS3 drugs alcohol smoking substance misuse effects',
  intro: 'The guidance asks for the effects of recreational drugs, including substance misuse, on behaviour, health and life processes. This lesson explains what drugs do, why they are addictive, and the damage they cause.',
  goals: ['Define a drug and distinguish medicinal and recreational drugs', 'Classify drugs as stimulants, depressants or hallucinogens, with examples', 'Describe the effects of alcohol, tobacco, solvents and illegal drugs', 'Explain addiction, tolerance and withdrawal'],
  points: [
    {tag: 'rule', title: 'What a drug is', text: 'A drug is a chemical that changes the way the body or mind works. <strong>Medicinal</strong> drugs (antibiotics, painkillers) treat illness. <strong>Recreational</strong> drugs are taken for their effect on mood or feelings; some are legal (alcohol, nicotine in tobacco, caffeine) and some illegal (cannabis, cocaine, heroin, ecstasy). <strong>Substance misuse</strong> means using any drug, including a medicine or a solvent, in a harmful way.'},
    {tag: 'rule', title: 'Stimulants', text: 'Stimulants speed up the nervous system: the heart beats faster and the person feels more alert. Examples: caffeine (coffee, cola), nicotine, cocaine, amphetamines. Large doses can cause anxiety, a racing heart and heart attacks.'},
    {tag: 'rule', title: 'Depressants', text: 'Depressants slow down the nervous system, so reactions are slower and judgement is poorer. Examples: alcohol, heroin, solvents. This is why drink-driving is so dangerous.'},
    {tag: 'rule', title: 'Hallucinogens and cannabis', text: 'Hallucinogens such as LSD change what a person sees and hears. Cannabis can cause relaxation but also anxiety and paranoia, and regular use, especially in teenagers, is linked to mental health problems. It is usually smoked, which also damages the lungs.'},
    {tag: 'rule', title: 'Alcohol', text: 'Alcohol is absorbed into the blood and reaches the brain within minutes. In the short term it slows reactions, affects balance and speech, and reduces self-control, leading to accidents and violence; a large amount at once can cause unconsciousness and death. In the long term it damages the <strong>liver</strong> (cirrhosis) and brain, raises blood pressure and the risk of several cancers, and can cause addiction.'},
    {tag: 'rule', title: 'Tobacco', text: 'Nicotine is highly addictive. Tobacco smoke also contains tar (causes lung cancer and damages cilia), carbon monoxide (reduces the oxygen the blood carries) and other chemicals that damage blood vessels and the heart. Smokers are far more likely to get lung cancer, heart disease, bronchitis and emphysema. Smoking in pregnancy harms the fetus.'},
    {tag: 'rule', title: 'Solvents and other illegal drugs', text: 'Inhaling solvents (glues, aerosols, lighter gas) damages the brain, liver, kidneys and lungs and can stop the heart, killing even a first-time user. Heroin is a powerful depressant and is extremely addictive; overdoses stop breathing, and sharing needles spreads HIV and hepatitis. Cocaine and ecstasy can cause dangerously high heart rate and body temperature.'},
    {tag: 'rule', title: 'Addiction, tolerance and withdrawal', text: 'Many drugs change chemicals in the brain so that the body comes to depend on them: <strong>addiction</strong>. With regular use, the body gets used to the drug, so more is needed for the same effect: <strong>tolerance</strong>. Stopping causes unpleasant <strong>withdrawal symptoms</strong> (shaking, sweating, anxiety, cravings), which makes it hard to give up.'},
    {tag: 'watch', title: 'Effects on life processes', text: 'Drugs affect the life processes you have studied: smoking reduces gas exchange and respiration, alcohol damages the liver that processes nutrients and toxins, many drugs suppress the appetite (nutrition) or the immune system, and drugs in pregnancy affect growth and reproduction.'}
  ],
  worked: [
    {q: 'A driver’s reaction time is 0.7 s sober and 1.2 s after drinking. At 20 m/s, how much further do they travel before braking?', steps: ['Sober: 20 × 0.7 = 14 m.', 'After drinking: 20 × 1.2 = 24 m.', 'Difference: 24 − 14 = 10 m.'], a: '10 m further: alcohol is a depressant and slows reactions.'},
    {q: 'Explain why a smoker finds it hard to stop smoking.', steps: ['Nicotine is addictive: the brain comes to depend on it.', 'Without it, the smoker has withdrawal symptoms such as cravings, irritability and anxiety.', 'Smoking again relieves them, so the habit continues.'], a: 'Addiction to nicotine and withdrawal symptoms make it hard to stop.'}
  ],
  quiz: [
    {q: 'Which of these is a depressant?', opts: ['Caffeine', 'Alcohol', 'Nicotine', 'Cocaine'], correct: 1, explain: 'Alcohol slows down the nervous system.'},
    {q: 'Which organ is most damaged by long-term heavy drinking?', opts: ['Lungs', 'Liver', 'Stomach', 'Kidneys'], correct: 1, explain: 'Cirrhosis of the liver.'},
    {q: 'Tolerance means:', opts: ['the drug no longer has any effect at all', 'more of the drug is needed for the same effect', 'the person can stop easily', 'the drug is legal'], correct: 1, explain: 'The body adapts to the drug.'},
    {q: 'Which part of tobacco smoke is addictive?', opts: ['Tar', 'Carbon monoxide', 'Nicotine', 'Smoke particles'], correct: 2, explain: 'Tar causes cancer; carbon monoxide reduces oxygen transport.'},
    {q: 'Why can solvent abuse kill a first-time user?', opts: ['It is addictive', 'It can make the heart stop', 'It causes lung cancer', 'It contains tar'], correct: 1, explain: 'Solvents can cause sudden heart failure.'}
  ],
  challenges: [
    {prompt: 'Describe the short-term and long-term effects of drinking alcohol on the body and on behaviour.', marks: 5, answer: 'Short term: alcohol is a depressant, so it slows reaction times, affects coordination, balance and speech, and reduces judgement and self-control, making accidents, risky behaviour and violence more likely; very large amounts can cause unconsciousness, vomiting and death. Long term: liver damage (cirrhosis), brain damage, high blood pressure and heart disease, increased risk of some cancers, addiction, and harm to an unborn baby if drunk in pregnancy.'},
    {prompt: 'Some medicines are also misused. Explain the difference between using a drug as a medicine and misusing it.', marks: 2, answer: 'A medicine is taken in the correct dose, for a medical reason, often as prescribed by a doctor, to treat an illness or symptoms. Misuse means taking it in a harmful way: too much, too often, without a medical reason, or for its effect on mood, which can cause harm, overdose or addiction.'}
  ],
  keywords: [['Drug', 'A chemical that changes how the body or mind works.'], ['Stimulant', 'A drug that speeds up the nervous system.'], ['Depressant', 'A drug that slows down the nervous system.'], ['Addiction', 'Physical or mental dependence on a drug.'], ['Tolerance', 'Needing more of a drug for the same effect.'], ['Withdrawal', 'Unpleasant symptoms when stopping a drug.']],
  stretch: 'At A level, drugs are explained at <strong>synapses</strong>, the gaps between nerve cells. Many drugs act there: nicotine mimics a neurotransmitter and triggers nerve impulses, while some drugs block the reuptake of dopamine, a chemical linked to reward, which is part of why they are addictive.'
});

/* ---------------- new physics lessons ---------------- */
lessonAfter('space', {id: 'sound-hearing', code: 'P12', subject: 'physics', title: 'Sound and hearing', level: 'GCSE',
  search: 'KS3 sound waves echoes hearing ear auditory range',
  intro: 'How sound is made, how it travels and reflects, and how your ear turns it into nerve signals. The guidance includes echoes and absorption, loudspeakers and microphones, the ear, the hearing ranges of humans and animals, and damage from loud sounds.',
  goals: ['Explain how sound is made and why it needs a medium', 'Compare the speed of sound in solids, liquids and gases, and use echoes to measure distance or speed', 'Describe how loudspeakers, microphones and the ear work', 'Link loudness to amplitude and pitch to frequency', 'Compare hearing ranges and describe how loud sounds damage hearing'],
  points: [
    {tag: 'rule', title: 'Sound comes from vibrations', text: 'Every sound is made by something vibrating: a guitar string, your vocal cords, a loudspeaker cone. The vibration pushes on the particles next to it, which push on their neighbours, so the vibration is passed along as a longitudinal wave of compressions and rarefactions.'},
    {tag: 'rule', title: 'Sound needs a medium', text: 'Because sound is passed on by particles, it needs a medium (solid, liquid or gas). It cannot travel through a vacuum: a ringing bell in a jar goes quiet as the air is pumped out, and in space no one can hear an explosion.'},
    {tag: 'rule', title: 'Speed of sound', text: 'About 340 m/s in air, about 1500 m/s in water, and about 5000 m/s in steel. Sound travels faster in liquids and solids because the particles are closer together and pass the vibration on more quickly. Light is enormously faster (300 000 000 m/s), which is why you see lightning before you hear thunder.'},
    {tag: 'rule', title: 'Reflection, echoes and absorption', text: 'Sound reflects off hard, smooth surfaces such as walls and cliffs: a reflected sound you hear separately is an <strong>echo</strong>. Soft, rough materials (curtains, carpets, foam) <strong>absorb</strong> sound, which is why empty rooms sound echoey and furnished rooms do not. Echoes are used in sonar and echo sounding (to measure sea depth), and bats and dolphins use them to find food (echolocation). Remember the sound goes there and back: distance = speed × time ÷ 2.'},
    {tag: 'rule', title: 'Loudness and pitch', text: 'A bigger <strong>amplitude</strong> of vibration means a louder sound. A higher <strong>frequency</strong> (more vibrations per second, measured in hertz, Hz) means a higher <strong>pitch</strong>. On an oscilloscope, a louder sound gives taller waves and a higher pitch gives more waves across the screen.'},
    {tag: 'rule', title: 'Loudspeakers and microphones', text: 'A loudspeaker turns electrical signals into sound: a changing current makes its cone vibrate back and forth, pushing the air. A microphone does the reverse: sound waves make its thin <strong>diaphragm</strong> vibrate, and this is turned into a changing electrical signal.'},
    {tag: 'rule', title: 'How we hear', text: 'The outer ear funnels sound down the ear canal to the <strong>eardrum</strong>, which vibrates. Three tiny bones (the ossicles) pass the vibrations on and make them bigger. They reach the fluid-filled <strong>cochlea</strong>, where tiny hair cells turn the vibrations into nerve impulses, which travel along the auditory nerve to the brain.'},
    {tag: 'rule', title: 'Hearing ranges', text: 'Humans hear from about 20 Hz to 20 000 Hz, and the upper limit falls as we age. Many animals hear different ranges: dogs hear much higher sounds than we do (which is why “silent” dog whistles work), bats hear and use ultrasound (above 20 000 Hz) for echolocation, and elephants communicate with infrasound (below 20 Hz) that travels long distances.'},
    {tag: 'watch', title: 'Loud sounds damage hearing', text: 'Very loud sounds can cause <strong>temporary deafness</strong> and ringing in the ears (tinnitus) after a concert. Repeated or extremely loud sounds can permanently damage the hair cells in the cochlea, and they do not grow back. Sound level is measured in decibels (dB); people who work with loud machines wear ear defenders.'}
  ],
  labs: ['sound'],
  worked: [
    {q: 'A ship sends a sound pulse down to the sea bed. The echo returns after 0.40 s. Sound travels at 1500 m/s in water. How deep is the sea?', steps: ['Total distance = speed × time = 1500 × 0.40 = 600 m.', 'This is there and back, so halve it.', 'Depth = 300 m.'], a: '300 m'},
    {q: 'A student stands 85 m from a wall and claps. The echo is heard 0.50 s later. Calculate the speed of sound.', steps: ['The sound travels to the wall and back: 2 × 85 = 170 m.', 'Speed = distance ÷ time = 170 ÷ 0.50.', '= 340 m/s.'], a: '340 m/s'}
  ],
  quiz: [
    {q: 'Sound travels fastest through:', opts: ['air', 'water', 'steel', 'a vacuum'], correct: 2, explain: 'Particles are closest in solids. Sound cannot travel through a vacuum at all.'},
    {q: 'Which part of the ear turns vibrations into nerve impulses?', opts: ['Eardrum', 'Ossicles', 'Cochlea', 'Ear canal'], correct: 2, explain: 'Hair cells in the cochlea.'},
    {q: 'A sound gets louder but stays the same pitch. What has changed?', opts: ['Frequency', 'Amplitude', 'Speed', 'Wavelength'], correct: 1, explain: 'Loudness depends on amplitude.'},
    {q: 'Why do empty rooms echo more than furnished ones?', opts: ['Sound travels faster', 'Hard surfaces reflect sound; soft furnishings absorb it', 'There is more air', 'The frequency changes'], correct: 1, explain: 'Curtains and carpets absorb sound.'},
    {q: 'Which animal uses ultrasound to find food?', opts: ['Elephant', 'Bat', 'Cow', 'Snake'], correct: 1, explain: 'Bats use echolocation with ultrasound.'},
    {q: 'In a microphone, what vibrates first?', opts: ['The cone', 'The diaphragm', 'The coil only', 'The wire'], correct: 1, explain: 'Sound makes the diaphragm vibrate.'}
  ],
  challenges: [
    {prompt: 'Describe how you could measure the speed of sound in air using echoes from a large wall. Say what you measure and how you would make it accurate.', marks: 5, answer: 'Stand a measured distance (e.g. 50 m, measured with a trundle wheel or tape) from a large flat wall. Clap and adjust the rate of clapping until each clap coincides with the echo of the previous one. Time 20 claps with a stopwatch; the time for one clap is the time for sound to travel there and back (2 × 50 m). Speed = 100 m ÷ time for one clap. Timing many claps reduces the effect of reaction time; repeat and average; avoid windy days.'},
    {prompt: 'Explain why someone who goes to many loud concerts may slowly lose the ability to hear high-pitched sounds.', marks: 3, answer: 'Very loud sound makes the hair cells in the cochlea vibrate violently, which damages them. The hair cells that detect high frequencies are especially easily damaged, and they cannot be replaced, so with repeated exposure the person gradually stops hearing high-pitched sounds. Temporary deafness after a concert is a warning sign.'}
  ],
  keywords: [['Medium', 'A substance (solid, liquid or gas) that a wave travels through.'], ['Echo', 'A reflected sound heard after the original.'], ['Amplitude', 'Size of the vibration; decides loudness.'], ['Frequency', 'Vibrations per second, in hertz; decides pitch.'], ['Cochlea', 'Part of the inner ear that turns vibrations into nerve impulses.'], ['Ultrasound', 'Sound above 20 000 Hz, too high for humans to hear.']],
  stretch: 'Sound intensity falls with distance by the inverse square law, and the decibel scale is <strong>logarithmic</strong>: every 10 dB increase means ten times the intensity, so 90 dB is a hundred times more intense than 70 dB. That is why a small increase in decibels can be much more damaging.'
});

lessonAfter('sound-hearing', {id: 'light-seeing', code: 'P13', subject: 'physics', title: 'Light, mirrors and seeing', level: 'GCSE',
  search: 'KS3 light reflection plane mirror pinhole camera luminous',
  intro: 'How we see things, how mirrors form images, how a pinhole camera works, and what happens when light meets different materials. The guidance includes all of these, plus refraction and dispersion (see also the Waves lesson).',
  goals: ['Explain how we see luminous and non-luminous objects', 'Describe how light travels and how fast', 'Use the law of reflection and describe the image in a plane mirror', 'Explain how a pinhole camera forms an image', 'Describe transmission, absorption and scattering, and how white light makes colours'],
  points: [
    {tag: 'rule', title: 'Luminous and non-luminous', text: '<strong>Luminous</strong> objects give out their own light: the Sun and other stars, flames, light bulbs, screens. <strong>Non-luminous</strong> objects do not: the Moon, planets, books and people. We see a non-luminous object because light from a source hits it and is scattered (reflected) off it, and some of that light enters our eyes.'},
    {tag: 'rule', title: 'How light travels', text: 'Light travels in straight lines in a uniform material, which is why shadows have sharp edges and you cannot see round corners. It travels at a finite but enormous speed: about 300 000 km/s in a vacuum. Unlike sound, light can travel through a vacuum, which is how sunlight reaches us across space.'},
    {tag: 'rule', title: 'Reflection', text: 'Smooth, shiny surfaces such as mirrors reflect light in one direction (regular reflection), obeying the <strong>law of reflection</strong>: angle of incidence = angle of reflection, both measured from the normal. Rough surfaces such as paper scatter light in all directions (<strong>diffuse scattering</strong>), so they look matt and do not form images.'},
    {tag: 'rule', title: 'Images in a plane mirror', text: 'The image in a flat mirror is the same size as the object, upright, the same distance behind the mirror as the object is in front, and laterally inverted (left and right swapped). It is a <strong>virtual</strong> image: the reflected rays only seem to come from behind the mirror, so it cannot be put on a screen. In a ray diagram, extend the reflected rays backwards with dotted lines; they meet at the image.'},
    {tag: 'rule', title: 'The pinhole camera', text: 'A pinhole camera is a box with a tiny hole at the front and a translucent screen at the back. Because light travels in straight lines, light from the top of an object goes through the hole to the bottom of the screen, and light from the bottom goes to the top. The image is <strong>upside down</strong> (inverted) and real. A bigger hole lets in more light, so the image is brighter but blurrier; moving the screen further from the hole makes the image bigger. Image height ÷ object height = image distance ÷ object distance.'},
    {tag: 'rule', title: 'Transmission and absorption', text: 'When light meets a material it can be transmitted, absorbed, reflected or scattered. <strong>Transparent</strong> materials (clear glass) transmit light clearly; <strong>translucent</strong> materials (frosted glass, tracing paper) transmit light but scatter it, so you cannot see clearly through them; <strong>opaque</strong> materials do not let light through. Absorbed light transfers energy to the material, warming it: dark surfaces absorb more than light ones.'},
    {tag: 'rule', title: 'Refraction and dispersion', text: 'Light changes direction when it passes from one material to another at an angle, because it changes speed (refraction). A prism splits white light into a spectrum, red, orange, yellow, green, blue, indigo and violet, because each colour is refracted by a slightly different amount (dispersion). Each colour of light has a different frequency: red the lowest, violet the highest.'},
    {tag: 'rule', title: 'Colour', text: 'White light is a mixture of all colours. A coloured object reflects (scatters) its own colour and absorbs the others: a red apple reflects red light. A white object reflects all colours; a black one absorbs them all. A coloured filter transmits only its own colour.'}
  ],
  labs: ['light'],
  worked: [
    {q: 'A tree 10 m tall is 20 m from a pinhole camera. The screen is 0.10 m behind the hole. How tall is the image?', steps: ['Image height ÷ object height = image distance ÷ object distance.', 'Image height = 10 × 0.10 ÷ 20.', '= 0.050 m = 5.0 cm, and upside down.'], a: '5.0 cm, inverted'},
    {q: 'You stand 1.5 m in front of a plane mirror. How far are you from your image? Then you step 0.5 m closer. How far now?', steps: ['The image is as far behind the mirror as you are in front: 1.5 m.', 'Distance from you to image = 1.5 + 1.5 = 3.0 m.', 'At 1.0 m from the mirror: 1.0 + 1.0 = 2.0 m.'], a: '3.0 m, then 2.0 m'}
  ],
  quiz: [
    {q: 'Which is luminous?', opts: ['The Moon', 'A candle flame', 'A mirror', 'A planet'], correct: 1, explain: 'The Moon and planets are seen by reflected sunlight.'},
    {q: 'The image in a plane mirror is:', opts: ['real and inverted', 'virtual, upright and laterally inverted', 'smaller than the object', 'in front of the mirror'], correct: 1, explain: 'Same size, same distance behind, left and right swapped.'},
    {q: 'The image in a pinhole camera is:', opts: ['upright', 'inverted', 'virtual', 'coloured differently'], correct: 1, explain: 'Rays cross over at the pinhole.'},
    {q: 'Making the pinhole bigger makes the image:', opts: ['dimmer and sharper', 'brighter and blurrier', 'smaller', 'upright'], correct: 1, explain: 'More light gets in, but rays from each point spread over a larger patch.'},
    {q: 'Frosted glass is:', opts: ['transparent', 'translucent', 'opaque', 'luminous'], correct: 1, explain: 'It lets light through but scatters it.'},
    {q: 'A green leaf looks green because it:', opts: ['absorbs green light', 'reflects green light and absorbs the other colours', 'gives out green light', 'refracts green light'], correct: 1, explain: 'It scatters green into our eyes.'}
  ],
  challenges: [
    {prompt: 'Explain fully how you are able to see this page in a lit room.', marks: 3, answer: 'Light from a luminous source (a lamp or the Sun) travels in straight lines to the page. The page is non-luminous and has a rough surface, so it scatters the light in all directions (diffuse reflection). Some of the scattered light travels in a straight line into your eye, and your brain forms an image. Dark ink absorbs most light, so the letters appear dark against the white paper, which reflects all colours.'},
    {prompt: 'Draw (on paper) a ray diagram to show how a plane mirror forms an image of a point object, and explain why the image is called virtual.', marks: 4, answer: 'Draw two rays from the object to the mirror, each reflecting with the angle of reflection equal to the angle of incidence (measured from normals drawn at 90° to the mirror). Extend the reflected rays backwards behind the mirror with dotted lines; they meet at the image, the same distance behind the mirror as the object is in front. The image is virtual because no light actually passes through that point; the rays only appear to come from it, so it cannot be projected on a screen.'}
  ],
  keywords: [['Luminous', 'Gives out its own light.'], ['Non-luminous', 'Seen only by the light it reflects or scatters.'], ['Diffuse scattering', 'Reflection in all directions from a rough surface.'], ['Virtual image', 'An image the rays only appear to come from; cannot be put on a screen.'], ['Translucent', 'Lets light through but scatters it.'], ['Dispersion', 'Splitting of white light into colours.']],
  stretch: 'At A level, light is shown to be both a wave and a stream of particles called <strong>photons</strong>. The energy of each photon is proportional to its frequency (E = hf), which is why violet and ultraviolet photons carry more energy than red ones, and why ultraviolet can damage skin cells.'
});

/* ---------------- additions to existing lessons (guidance points that were only partly covered) ---------------- */
extendLesson('particles', {points: [
  {tag: 'rule', title: 'Brownian motion', text: 'In 1827 the botanist Robert Brown saw tiny particles from pollen grains jiggling randomly in water under a microscope. You can see the same with smoke particles in air. The jiggling is caused by invisible, fast-moving water or air molecules hitting the much bigger particles unevenly from all sides. Brownian motion is evidence that matter is made of particles that are constantly moving, and it is faster at higher temperatures.'}
], deep: [['Brownian motion: seeing the evidence', '<p>Nobody can see a single air molecule, so how do we know they exist and are moving? Look at smoke in a small glass cell under a microscope, lit from the side. The bright specks of smoke jiggle about randomly, changing direction all the time. A smoke particle is far bigger than an air molecule, but it is being hit by enormous numbers of fast-moving air molecules from every direction. At any instant, slightly more hit one side than the other, so it is nudged that way, then another way. This random, zigzag movement is Brownian motion. It was a key piece of evidence for the particle model, and Einstein used it in 1905 to estimate the size of molecules.</p>']]});

extendLesson('periodic', {points: [
  {tag: 'rule', title: 'Physical properties of elements', text: 'Elements vary widely in appearance, state at room temperature, magnetism, and conduction of heat and electricity, and these properties are used to classify them as metals or non-metals. Most metals are shiny solids that conduct well (mercury is a liquid metal). Non-metals at room temperature can be solids (carbon, sulfur, iodine), one liquid (bromine), or gases (oxygen, nitrogen, chlorine), and most are poor conductors (graphite is an exception). Only a few elements are magnetic: iron, nickel and cobalt (and steel, which is mostly iron).'},
  {tag: 'rule', title: 'Symbols and formulae', text: 'Each element has a symbol of one or two letters; the first is a capital: H, O, C, Na (sodium, from its Latin name natrium), Fe (iron, from ferrum), Cl. A formula shows which elements are in a compound and how many atoms of each: H₂O has 2 hydrogen atoms and 1 oxygen atom; CO₂ has 1 carbon and 2 oxygen; NaCl has sodium and chlorine in a 1:1 ratio.'}
]});

extendLesson('separating', {points: [
  {tag: 'rule', title: 'Solubility in different solvents', text: 'A substance may dissolve well in one solvent but not in another. Salt dissolves in water but not in oil; nail varnish does not dissolve in water but does dissolve in propanone (nail-varnish remover); iodine dissolves much better in ethanol than in water. Most solids are more soluble in hot solvent than in cold, and a solution that holds the maximum amount at that temperature is saturated. This is why chromatography and crystallisation depend on choosing the right solvent.'}
]});

extendLesson('motion', {points: [
  {tag: 'rule', title: 'Relative motion', text: 'Speeds are always measured relative to something. Two cars on a motorway going the same way at 30 m/s and 25 m/s have a relative speed of 30 − 25 = 5 m/s: the faster one gains 5 m every second. Two trains approaching each other at 30 m/s and 20 m/s close the gap at 30 + 20 = 50 m/s. For trains passing, the time to pass = total length to be covered ÷ relative speed.'}
], deep: [['Relative motion: trains and cars passing', '<p>How fast something seems to move depends on who is watching. If you are in a train going at 30 m/s and another train on the next track goes the same way at 32 m/s, it seems to creep past you at only 2 m/s. If it comes the other way at 32 m/s, it flashes past at 62 m/s. To find how long one vehicle takes to pass another, work out the distance that has to be covered relative to the other (usually the sum of their lengths) and divide by the relative speed. A 200 m train overtaking a 100 m train at a relative speed of 5 m/s takes 300 ÷ 5 = 60 s to pass completely; if they were moving towards each other at a combined 50 m/s, it would take only 300 ÷ 50 = 6 s.</p>']]});

extendLesson('forces', {points: [
  {tag: 'rule', title: 'Friction and resistance', text: 'Friction acts between two surfaces that rub or try to slide over each other, always opposing the motion. It causes heating and wear, but it is also essential: it gives tyres and shoes grip and makes brakes work. It is reduced by lubrication (oil) and smooth surfaces. Objects moving through air or water must push it out of the way, producing air resistance or water resistance (drag), which increases with speed; streamlined shapes reduce it.'},
  {tag: 'rule', title: 'Forces in balance on everyday objects', text: 'A weight hanging from a stretched spring is in equilibrium: the spring pulls up with a force equal to the weight. A book on a table squashes the surface very slightly, and the surface pushes back up with a reaction force equal to the weight.'}
]});

extendLesson('moments', {points: [
  {tag: 'rule', title: 'Simple machines: no free lunch', text: 'Levers, pulleys, ramps and gears let a small force move a large load, but the small force must move through a larger distance. Ideally, force × distance moved is the same at both ends (the work done is the same), so a lever that multiplies the force by 5 makes the load move only one fifth as far. In real machines friction wastes some energy, so you get out a little less than you put in.'}
]});

extendLesson('energy', {points: [
  {tag: 'rule', title: 'The Sun: the source of most energy resources', text: 'Most of our energy resources come from the Sun. Food and biomass store energy captured by photosynthesis. Coal, oil and gas are fossil fuels: coal formed from plants, and oil and gas from tiny sea organisms, buried for millions of years under heat and pressure, so the chemical energy they release was originally sunlight. The Sun also drives the weather, so wind and waves are indirectly solar too. Batteries are a store of chemical energy, not a source.'},
  {tag: 'rule', title: 'Generating electricity', text: 'In most power stations a fuel (coal, gas, biomass or nuclear) heats water to make steam, which spins a turbine connected to a generator. Wind, waves, tides and hydroelectric dams spin turbines directly. Solar cells turn light straight into electricity. Each resource has advantages and disadvantages in cost, reliability and pollution.'}
]});

extendLesson('magnetism', {points: [
  {tag: 'rule', title: 'The Earth’s magnetism and navigation', text: 'The Earth behaves like a giant bar magnet. A compass needle is a small magnet that lines up with the Earth’s field, so its north-seeking pole points north, which has helped people navigate for centuries. Compasses are also used to plot the shape of a magnet’s field: the needle points along the field lines.'},
  {tag: 'rule', title: 'Electromagnets in devices', text: 'Lifting magnets in scrapyards pick up steel and drop it when switched off. A <strong>relay</strong> uses a small current in an electromagnet to attract a switch that turns on a much larger current, such as a car’s starter motor, so the driver’s switch can be small and safe. Electric bells, loudspeakers and DC motors also use electromagnets.'}
]});

extendLesson('space', {points: [
  {tag: 'rule', title: 'The Sun’s apparent movement', text: 'The Earth spins from west to east once a day, so the Sun appears to rise in the east, move across the southern sky (seen from the UK) and set in the west; the stars also appear to move across the night sky, circling around the Pole Star. As the Earth orbits the Sun through the year, the Sun’s midday height changes (high in summer, low in winter) and we see different constellations at night.'},
  {tag: 'rule', title: 'Day length and the hemispheres', text: 'In summer days are long and nights short; in winter the opposite. When it is summer in the northern hemisphere it is winter in the southern hemisphere, because the north is tilted towards the Sun while the south is tilted away. Near the equator, day length stays close to 12 hours all year; near the poles there can be 24 hours of daylight or darkness.'},
  {tag: 'rule', title: 'Light sources in space', text: 'The Sun and other stars are luminous: they give out their own light. Planets, moons, comets and satellites are seen only because they reflect sunlight.'},
  {tag: 'rule', title: 'Satellites and probes', text: 'A satellite is anything that orbits a larger body: the Moon is a natural satellite. Artificial satellites are used for communications and TV, navigation (GPS), weather forecasting, observing and mapping the Earth, and as space telescopes such as Hubble that see clearly above the atmosphere. Space probes, such as the Voyager probes and Mars rovers, travel to other planets to explore the Solar System.'}
]});

extendLesson('plants', {title: 'Plants: transport, roots and minerals', points: [
  {tag: 'rule', title: 'Root hairs and minerals', text: 'Root hair cells have long, thin extensions that give a huge surface area for absorbing water (by osmosis) and mineral ions (often by active transport) from the soil. Plants get carbon, hydrogen and oxygen from carbon dioxide and water, but they also need other elements: <strong>nitrogen</strong> (as nitrates) to make proteins for growth, <strong>phosphorus</strong> (phosphates) for roots and respiration, <strong>potassium</strong> for healthy leaves and flowers, and <strong>magnesium</strong> to make chlorophyll. Without them plants show deficiency symptoms, such as stunted growth (nitrate) or yellow leaves (magnesium). Farmers add fertilisers containing these elements.'}
]});

extendLesson('ecology', {points: [
  {tag: 'rule', title: 'Predation and competition control populations', text: 'Populations rise and fall with predators and resources. When prey are plentiful, predators have more food and their numbers rise; then they eat more prey, so the prey fall, and later the predators fall too: the populations cycle, with the predator peak just after the prey peak. Organisms also compete for limited resources: plants for light, water, minerals and space; animals for food, water, territory and mates. The best competitors survive and the population is held at a size the environment can support.'},
  {tag: 'rule', title: 'Growth of a bacterial population', text: 'In good conditions bacteria divide in two about every 20 minutes, so a population doubles again and again. Grown in a flask, it shows a lag phase (adjusting), then rapid (exponential) growth, then levels off as food runs out and waste builds up (stationary phase), and finally falls (death phase). Vegetation behaves similarly: plants grow quickly into bare ground until they compete for light and space.'},
  {tag: 'rule', title: 'Protecting living things: sustainable development', text: 'Sustainable development means meeting our needs today without stopping future generations meeting theirs. Ways to protect living things and the environment include nature reserves and protected areas, breeding programmes for endangered species, seed banks, fishing quotas and bigger net holes so young fish escape, replanting forests, reducing pollution, recycling, and using renewable energy.'}
], deep: [['Populations: predators, prey and competition', '<p>No population can grow for ever. Picture rabbits and foxes. When there are lots of rabbits, foxes have plenty of food, raise more cubs, and the fox population rises. More foxes eat more rabbits, so the rabbit population falls. Now food is scarce for the foxes and their numbers fall too, which lets the rabbits recover. On a graph, the two populations rise and fall in repeating cycles, with the predator curve lagging a little behind the prey curve. At the same time, members of a population compete for whatever is in short supply: food, water, light, space, mates. Bacteria in a flask show the whole story in hours: slow at first, then doubling every generation, then levelling off when food runs out and waste builds up, then declining.</p>']]});

extendLesson('health', {points: [
  {tag: 'rule', title: 'How bacteria and viruses multiply', text: 'Bacteria reproduce by splitting in two (binary fission); in warm, moist conditions with food this can happen every 20 minutes, so numbers rise very quickly, which is why food left out can soon cause food poisoning. Viruses cannot reproduce on their own: they enter a host cell and make it build new viruses, which burst out and infect more cells.'}
]});

/* ---------------- "Explained in full" for the new lessons ---------------- */
DEEP['repro-human'] = [
  ['From puberty to fertility', '<p>Before puberty, the reproductive organs are present but not working. During puberty, between roughly 10 and 16, the testes start making sperm and the ovaries start releasing eggs, and the body changes to look adult. A boy then makes millions of sperm every day for the rest of his life. A girl is born with all the eggs she will ever have, stored in her ovaries, and from puberty to the menopause (around age 50) usually releases one a month.</p>'],
  ['The monthly cycle, step by step', '<p>The menstrual cycle prepares the body for a possible pregnancy each month. It is counted from the first day of a period. For about five days, the old lining of the uterus breaks down and passes out of the vagina with a little blood. Over the next week or so, a new lining builds up, thick and full of blood vessels, so that it could feed an embryo. Around day 14, an egg is released from an ovary and travels slowly along the oviduct. If it meets sperm and is fertilised, the embryo implants in the thick lining and the lining is kept. If not, the egg dies within a day or so, the lining breaks down, and a new period starts the next cycle. Cycles vary between people and are often irregular at first.</p>'],
  ['Fertilisation to implantation', '<p>Sperm swim from the vagina through the cervix and uterus into the oviducts; of millions released, only a few hundred reach the egg and only one gets in. When its nucleus fuses with the egg nucleus, the 23 chromosomes from each parent combine to give a zygote with the full 46. Over the next week it divides into a hollow ball of cells as cilia waft it down the oviduct, then it embeds itself in the uterus lining.</p>'],
  ['Nine months of development', '<p>In the first eight weeks the embryo forms all its main organs; the heart begins to beat at around 6 weeks. From then on, as a fetus, it mainly grows and matures. The placenta develops where the embryo implanted: finger-like projections give a huge surface area where the fetus’s blood vessels come very close to the mother’s blood. Oxygen and nutrients diffuse across into the fetus’s blood and travel along the umbilical cord; carbon dioxide and urea travel the other way to be removed by the mother. Because harmful substances such as alcohol, nicotine, carbon monoxide and some drugs and viruses can also cross, a pregnant woman’s lifestyle directly affects her baby.</p>'],
  ['Birth and afterwards', '<p>At about 40 weeks, the strong muscles of the uterus begin regular contractions. The cervix gradually widens to about 10 cm, the amniotic sac breaks, and the contractions push the baby out through the vagina. The baby takes its first breath and its lungs start working; until now it got its oxygen from the placenta. The cord is cut, leaving the navel, and the placenta is delivered. Breast milk provides the right nutrients and antibodies that help protect the baby while its own immune system develops.</p>']
];
DEEP['repro-animals'] = [
  ['Different solutions to the same problem', '<p>Every animal faces the same problem: getting a sperm to an egg, and then giving the young a chance to survive. Animals that live in water can simply release eggs and sperm into it, which keeps the gametes moist. This external fertilisation is wasteful, because many gametes never meet and the eggs and young are unprotected, so these animals release enormous numbers. Animals on land cannot do this, because gametes would dry out, so they fertilise internally, placing sperm inside the female’s body.</p>'],
  ['Protecting the developing young', '<p>After fertilisation, the embryo needs food, water, oxygen and protection. A bird’s or reptile’s egg provides all of these in a package: a yolk for food, a shell that lets oxygen in, and membranes that keep it moist. Mammals keep the embryo inside the mother, connected to her blood by a placenta, which gives the best protection of all, and then feed the newborn on milk. The more an animal invests in each offspring, the fewer it can produce, but the more of them survive.</p>'],
  ['Life cycles and metamorphosis', '<p>Many animals look quite different as young and adults. A tadpole is built for life in water (gills, a tail) while a frog is built for land (lungs, legs); the change is metamorphosis. In insects with complete metamorphosis, the larva (such as a caterpillar) spends its time feeding and growing, the pupa reorganises the body, and the adult reproduces and spreads. Because larvae and adults often eat different food, they do not compete with each other.</p>']
];
DEEP['repro-plants'] = [
  ['A flower is a reproductive organ', '<p>Flowers exist to make seeds. The male gametes are inside pollen grains made in the anthers; the female gametes are inside ovules in the ovary. The problem is that plants cannot move, so pollen must be carried from one flower to another, by insects or the wind. Everything about a flower’s shape, colour and smell is an adaptation for one of these.</p>'],
  ['From pollination to seed', '<p>When a pollen grain of the right species lands on a stigma, sugars on the stigma make it germinate: it grows a tube down through the style towards an ovule, digesting its way through. The male nucleus moves down the tube and fuses with the female nucleus inside the ovule. Each ovule needs its own pollen grain, which is why a pea pod can have some seeds missing. After fertilisation, the ovule develops into a seed containing an embryo (a tiny root and shoot) and a food store, inside a protective coat, while the ovary wall grows into the fruit. The petals, no longer needed, wither.</p>'],
  ['Why dispersal matters, and how to measure it', '<p>Seedlings that grow next to their parent are shaded by it and must share its water and minerals, so most would die. Fruits are adaptations for carrying seeds away: wings and parachutes catch the wind, juicy flesh tempts animals to eat them and drop the seeds elsewhere, hooks cling to fur, and drying pods split explosively. To investigate a dispersal mechanism quantitatively, choose something you can measure, such as the time a winged seed takes to fall or the distance it travels from a fan, change one feature at a time, repeat each measurement, and plot the means on a graph.</p>']
];
DEEP['classification'] = [
  ['How classification works', '<p>Classification sorts living things into groups within groups. The biggest groups (kingdoms) share only a few basic features, while the smallest (species) share almost everything. A lion and a tiger are in the same genus (<em>Panthera</em>) because they are very similar, but are different species because they do not normally interbreed. Grouping by shared features usually also reflects shared ancestry: organisms in the same group evolved from a common ancestor.</p>'],
  ['Telling the vertebrate classes apart', '<p>The key questions are about skin covering, how they breathe, and how they reproduce. Scales and gills mean fish. Moist skin and a life cycle that starts in water mean amphibians. Dry scales and leathery eggs on land mean reptiles. Feathers mean birds. Hair and milk mean mammals. Body temperature is another clue: birds and mammals keep a constant body temperature, while fish, amphibians and reptiles take on the temperature of their surroundings.</p>'],
  ['Life as a single cell', '<p>A single-celled organism has to do everything (feeding, moving, getting rid of waste, reproducing) with one cell. Being tiny gives a large surface area for its volume, so oxygen and carbon dioxide can diffuse across the membrane fast enough. In fresh water, water constantly enters by osmosis, so freshwater protists have contractile vacuoles that pump it out. Amoeba changes shape to move and engulf food; Paramecium uses cilia; Euglena uses a flagellum and makes its own food with chloroplasts. Their features show how even one cell can be highly adapted.</p>']
];
DEEP['drugs'] = [
  ['How drugs affect behaviour', '<p>Your nervous system carries messages as electrical impulses along nerve cells, passed from one cell to the next by chemicals. Most recreational drugs act on this system. Stimulants make messages pass faster, so a person feels alert and energetic but can become anxious and have a racing heart. Depressants slow messages down, so a person feels relaxed but reacts slowly, loses coordination and makes poor decisions. That is why alcohol is involved in so many accidents and why driving after drinking is illegal.</p>'],
  ['Why drugs are hard to give up', '<p>Many drugs trigger the brain’s reward system, producing pleasant feelings. With repeated use, the brain adapts: the person needs more to get the same effect (tolerance) and feels unwell without it (withdrawal). They may come to depend on the drug physically and mentally (addiction), continuing to use it even when it harms their health, relationships and work. Heroin and nicotine are among the most addictive substances known.</p>'],
  ['Damage to health and life processes', '<p>Drugs harm more than behaviour. Smoking damages the lungs, cutting gas exchange and causing cancer and heart disease. Long-term heavy drinking damages the liver, brain and heart. Solvents can cause instant death by heart failure. Injecting drugs with shared needles spreads infections such as HIV and hepatitis. Drugs taken in pregnancy cross the placenta and affect the baby’s growth. In each case, the drug interferes with a normal life process: breathing, nutrition, excretion, growth or reproduction.</p>']
];
DEEP['sound-hearing'] = [
  ['From vibration to wave', '<p>When a drum skin moves outwards it squashes the air next to it into a compression; when it moves back it leaves a region where the air is spread out, a rarefaction. Each layer of air pushes the next, so the pattern of compressions and rarefactions travels outwards while each particle just vibrates back and forth around its usual position. The closer and more tightly linked the particles, the faster the vibration is passed on, which is why sound is faster in water and fastest in solids, and why it cannot cross a vacuum at all.</p>'],
  ['Echoes at work', '<p>When sound hits a hard surface, much of it reflects. If the reflection arrives a noticeable time after the original sound, you hear an echo. Because sound has a known speed, timing an echo gives a distance: ships measure sea depth and find shoals of fish this way (sonar), and bats and dolphins locate prey by listening to the echoes of their own high-pitched calls. Concert halls and recording studios use soft, absorbent materials to stop unwanted echoes.</p>'],
  ['Inside the ear', '<p>Sound waves are funnelled into the ear canal and make the eardrum vibrate at the same frequency. Three tiny bones, the smallest in the body, pass these vibrations to the cochlea, a coiled tube full of liquid, and make them stronger. Inside the cochlea, thousands of hair cells are each sensitive to different frequencies; when they move, they send impulses along the auditory nerve to the brain. Extremely loud sounds shake these hair cells so violently that they are damaged; a little damage causes temporary deafness and ringing, but repeated damage is permanent, because hair cells do not regrow.</p>']
];
DEEP['light-seeing'] = [
  ['Why we can see anything', '<p>You see an object when light from it enters your eye. Luminous objects make their own light. Everything else, including this page, the Moon and other people, is seen only because light from a source has bounced off it into your eye. A smooth mirror reflects light in an orderly way, so you see an image in it; rough surfaces scatter light in every direction, so you can see them from anywhere in the room but they do not show an image.</p>'],
  ['Mirror images', '<p>When you look in a mirror, light from your face reflects off the mirror into your eyes. Your brain assumes light travels in straight lines, so it traces the rays back to where they seem to come from: a point behind the mirror. That is why the image appears to be behind the glass, at the same distance as you are in front. No light really goes there, so the image is virtual. Left and right appear swapped, which is why ambulances have their name written backwards on the front, so drivers read it correctly in their mirrors.</p>'],
  ['The pinhole camera and straight-line light', '<p>Because light travels in straight lines, each point of an object sends only a thin beam through a tiny hole, landing on just one spot on the screen. Rays from the top of the object, travelling down through the hole, land at the bottom of the screen, and rays from the bottom land at the top, so the image is upside down. A larger hole lets each point send a wider beam, which overlaps with neighbouring points, making the image brighter but blurred. The eye works in a similar way, with a lens to make a bright, sharp image, and the brain turns the upside-down image the right way up.</p>']
];

